"""Arrange students into printable seating rows."""

from typing import Iterable, List, Tuple

from rosterkit.models import Student

# ---
def seating_rows(
    students: Iterable[Student], seats: int
) -> List[str]:
    """One line per row, students sorted by last name."""
    roster = sorted(students, key=last_first)
    if seats <= 0 or not roster:
        raise ValueError("need students and seats > 0")
    return format_rows(roster, seats)

# ---
def last_first(student: Student) -> Tuple[str, str]:
    last = student.last_name.casefold()
    first = student.first_name.casefold()
    return (last, first)

# ---
def format_rows(
    roster: List[Student], seats: int
) -> List[str]:
    starts = range(0, len(roster), seats)
    return [
        row_text(number, roster[start:start + seats])
        for number, start in enumerate(starts, 1)
    ]

# ---
def row_text(number: int, group: List[Student]) -> str:
    names = " | ".join(item.display_name for item in group)
    return f"Row {number}: {names}"

