import unittest

from rosterkit.seating import seating_rows
from rosterkit.models import Student

# ---
def make_student(last_name, first_name):
    student_id = f"{last_name}-{first_name}"
    return Student(student_id, last_name, first_name, "A")

class SeatingRowTests(unittest.TestCase):
    def setUp(self):
        self.students = [
            make_student("Varrow", "Ines"),
            make_student("Halloway", "Juno"),
            make_student("Thistle", "Bram"),
            make_student("Dunmere", "Piet")
        ]

    def test_rows_follow_last_name_order(self):
        self.assertEqual(
            seating_rows(self.students, 2),
            [
                "Row 1: Dunmere, Piet | Halloway, Juno",
                "Row 2: Thistle, Bram | Varrow, Ines"
            ]
        )

    def test_last_row_may_be_short(self):
        rows = seating_rows(self.students[:3], 2)
        self.assertEqual(rows[-1], "Row 2: Varrow, Ines")
        self.assertEqual(len(rows), 2)

    def test_seat_count_larger_than_roster(self):
        rows = seating_rows(self.students, 10)
        self.assertEqual(len(rows), 1)
        self.assertIn("Row 1: Dunmere, Piet", rows[0])

    def test_same_last_name_sorts_by_first_name(self):
        students = [
            make_student("Smith", "Zed"),
            make_student("Smith", "Ann")
        ]
        self.assertEqual(
            seating_rows(students, 2),
            ["Row 1: Smith, Ann | Smith, Zed"]
        )

    def test_empty_roster_raises(self):
        with self.assertRaises(ValueError):
            seating_rows([], 2)

    def test_zero_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, 0)

    def test_negative_seats_raises(self):
        with self.assertRaises(ValueError):
            seating_rows(self.students, -3)
